pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData, address caller) public {
        vm.assume(caller != address(this));

        bool emitted;
        vm.recordLogs();
        vm.prank(caller);
        try c.requestPrice(identifier, time, ancillaryData) {} catch {}
        Vm.Log[] memory logs = vm.getRecordedLogs();
        for (uint i = 0; i < logs.length; i++) {
            if (logs[i].emitter == address(c)) {
                emitted = true;
                break;
            }
        }

        assertTrue(!emitted);
    }
}

