pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        vm.assume(msg.sender != address(c.optimisticAsserter()));
        vm.recordLogs();
        bool ok = true;
        try c.requestPrice(identifier, time, ancillaryData) {
            ok = true;
        } catch {
            ok = false;
        }
        Vm.Log[] memory logs = vm.getRecordedLogs();
        uint256 eventCount = 0;
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].topics[0] == keccak256("PriceRequestAdded(bytes32,uint256,bytes)")) {
                eventCount++;
            }
        }
        assertTrue(ok ? eventCount == 1 : eventCount == 0);
    }
}

