pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 identifier, uint256 time, bytes calldata ancillaryData, address caller) public {
        vm.assume(caller != address(this)); // caller must NOT be the optimistic asserter to trigger revert
        vm.assume(caller != address(0));

        vm.recordLogs();
        bool reverted;
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }
        Vm.Log[] memory logs = vm.getRecordedLogs();

        // If the call reverted, no PriceRequestAdded event must have been emitted.
        assertTrue(!reverted || logs.length == 0);
    }
}

